<script lang="ts">
 import {onMount} from 'svelte';
 import {Box,Search,FolderOpen,AlertTriangle,ExternalLink,Download,Check} from 'lucide-svelte';
 import {call,asset} from './api';
 import {statuses,visibleRows,indexedRows,needsReview,type Summary,type Row,type Settings} from './model';
 let {summary,folder,settings,preview=false,onerror,onopen,onpreview}:{summary:Summary|null;folder:string;settings:Settings;preview?:boolean;onerror:(e:unknown)=>void;onopen:()=>void;onpreview:()=>void}=$props();
 let query=$state(''),filter=$state(''),page=$state(0),selected=$state<number|null>(null),frame=$state(''),frameKind=$state('preview'),viewer=$state<HTMLIFrameElement>(),loaded=$state(false),pendingFocus=false;
 const all=$derived(summary?indexedRows(summary):[]),rows=$derived(visibleRows(all,query,filter)),pageRows=$derived(rows.slice(page*100,page*100+100)),current=$derived(selected===null?null:all[selected]);
 const review=$derived(all.filter(needsReview)),alignment=$derived((summary?.alignment||{}) as {applied?:boolean;translation_B_to_A_mm?:number[];rotation_B_to_A?:number[][];status?:string});
 const complete=$derived(summary?.analysis_complete===true&&review.length===0);
 const palette=$derived((summary?.colors_hex||{}) as Record<string,string>);
 function color(status:string){return palette[status]||settings.palette[(status==='RENAMED'?'SAME':status).toLowerCase()]||'#94a3b8';}
 function number(value:unknown,unit='mm'){return typeof value==='number'&&Number.isFinite(value)?`${value.toLocaleString('pl',{maximumFractionDigits:4})} ${unit}`:'Nie podano';}
 function pair(r:Row){return `A[${r.a_index??'—'}] → B[${r.b_index??'—'}]`;}
 function command(action:string,focus=false){if(loaded&&frameKind==='preview')viewer?.contentWindow?.postMessage({type:'dscompare:command',action,record_index:selected,focus,pair:focus},'*');}
 async function show(kind='preview',focus=false){try{pendingFocus=focus;if(frame&&frameKind===kind){command('select',focus);return;}loaded=false;const path=await call<string>('artifact_path',{folder,name:kind==='preview'?'PODGLAD_KOLOROW_3D.html':kind==='bomA'?'BOM_A.html':kind==='bomB'?'BOM_B.html':'RAPORT.html'});frameKind=kind;frame=asset(path);}catch(e){onerror(e)}}
 async function output(name:string){try{await call('open_artifact',{folder,name})}catch(e){onerror(e)}}
 function select(r:Row){selected=Number(r.record_index);command('select');}
 function setFilter(value:string){filter=filter===value?'':value;page=0;command(filter==='CHANGES'?'changes':'all');}
 function receive(e:MessageEvent){if(e.source!==viewer?.contentWindow||!e.data)return;
  if(e.data.type==='dscompare:ready'){if(frameKind!=='preview'){onpreview();show('preview',true);return;}loaded=true;viewer?.contentWindow?.postMessage({type:'dscompare:command',action:'configure',embedded:true},'*');if(selected!==null)command('select',pendingFocus);pendingFocus=false;}
  if(e.data.type==='dscompare:selected'&&e.data.record_index===null&&loaded)selected=null;
  if(e.data.type==='dscompare:selected'&&Number.isInteger(e.data.record_index)&&all[e.data.record_index]){selected=e.data.record_index;let index=rows.findIndex(r=>r.record_index===selected);if(index<0){filter='';query='';index=selected??0;}page=Math.floor(index/100);}
 }
 onMount(()=>{window.addEventListener('message',receive);return()=>window.removeEventListener('message',receive)});
 let lastFolder='',lastPreview=false;
 $effect(()=>{if(folder!==lastFolder){lastFolder=folder;frame='';selected=null;query='';filter='';page=0;frameKind='preview';if(preview&&folder&&summary?.preview_3d)show();}else if(preview&&!lastPreview&&folder)show();lastPreview=preview;});
</script>
<div class="page-heading"><div><span class="eyebrow">REZULTAT ANALIZY</span><h2>Wyniki porównania</h2><p>Otwieraj raporty, kolorowy STEP i podgląd 3D bez dodatkowej tabeli części.</p></div><button onclick={()=>folder?output('folder'):onopen()}><FolderOpen size={16}/>{folder?'Folder wyników':'Otwórz wyniki'}</button></div>
{#if summary}
 <section class="analysis-summary panel" aria-label="Podsumowanie analizy"><span class:warning={!complete} class="analysis-badge">{#if complete}<Check size={16}/>{:else}<AlertTriangle size={16}/>{/if}{complete?'Analiza pełna':summary.analysis_complete===false?'Analiza częściowa':'Zakres wymaga sprawdzenia'}</span><span>A: <strong>{summary.solids_A??'—'}</strong> · B: <strong>{summary.solids_B??'—'}</strong></span><button onclick={()=>setFilter('DIAGNOSTIC')}>Do sprawdzenia: {review.length}</button></section>
 {#if !complete}<div class="banner warning" role="note">Niepotwierdzone różnice materiału oznaczono „Do sprawdzenia”.</div>{/if}
 {#if !preview}
 <div class="toolbar"><button onclick={()=>output('RAPORT.html')}><ExternalLink size={15}/>Raport HTML / PDF</button><button disabled={summary.full_bom===false} onclick={()=>output('MASA_MATERIALY.html')}><ExternalLink size={15}/>Masa i materiały · HTML</button><button disabled={!summary.preview_3d} onclick={()=>output('PODGLAD_KOLOROW_3D.html')}><Box size={15}/>Podgląd 3D · HTML</button><button disabled={summary.step_ready===false} onclick={()=>output('POROWNANIE_KOLORY.step')}><Download size={15}/>Kolorowy STEP</button><button disabled={summary.full_bom===false} onclick={()=>output('BOM_A.html')}>BOM A · HTML</button><button disabled={summary.full_bom===false} onclick={()=>output('BOM_B.html')}>BOM B · HTML</button><button onclick={()=>output('ZMIANY.csv')}>Zmiany CSV</button>{#if summary.bom_csv!==false}<button onclick={()=>output('BOM_A.csv')}>BOM A CSV</button><button onclick={()=>output('BOM_B.csv')}>BOM B CSV</button>{/if}</div>
 {/if}
 <div class="review-workspace" class:list-mode={!preview&&frameKind==='preview'} class:preview-mode={preview}>
  {#if preview||frameKind!=='preview'}<section class="review-viewer viewer"><div class="viewer-bar"><span>{frameKind==='report'?'Raport HTML':frameKind==='bomA'?'BOM A · HTML':frameKind==='bomB'?'BOM B · HTML':'Podgląd 3D'}</span>{#if frameKind!=='preview'}<button onclick={()=>{frameKind='preview';frame='';if(preview)show()}}>Zamknij raport</button>{/if}</div>{#if frame}<iframe bind:this={viewer} title={frameKind==='preview'?'Podgląd modeli 3D':'Raport porównania'} src={frame} sandbox="allow-scripts allow-downloads"></iframe>{:else}<div class="empty"><Box size={36}/><p>Podgląd jest dostępny, jeśli został wygenerowany podczas analizy.</p><button onclick={()=>show()}>Otwórz podgląd 3D</button></div>{/if}</section>
  {/if}{#if current}<aside class="part-details panel" aria-label="Szczegóły części">{#if current}<span class="eyebrow">POZYCJA {Number(current.record_index)+1}</span><h2>{statuses[current.status]||current.status}</h2><dl><dt>Poprzednia A</dt><dd>{current.name_a||'—'}</dd><dt>Nowa B</dt><dd>{current.name_b||'—'}</dd></dl><h3>Ruch części A → B</h3><dl>{#each [['X','delta_x'],['Y','delta_y'],['Z','delta_z'],['Odległość środka','distance_mm']] as [label,key]}<dt>{label}</dt><dd>{number(current[key])}</dd>{/each}<dt>Obrót dopasowania</dt><dd>{number(current.rotation_deg,'°')}</dd></dl><h3>Weryfikacja</h3><p>{needsReview(current)?'Wymaga sprawdzenia':current.confidence||'Status z zapisanego wyniku'}</p><p class="diagnostic-reason">{String(current.diagnostic_reason||current.note||'Brak dodatkowych uwag.')}</p>{#if current.blocked_operation_operand}<div class="banner warning">Element uczestniczył w operacji zakończonej błędem. To nie przesądza o poprawności pozostałych elementów.</div>{/if}<button disabled={!summary.preview_3d} onclick={()=>output('PODGLAD_KOLOROW_3D.html')}><Box size={15}/>Otwórz podgląd HTML</button><button onclick={()=>{selected=null;command('clear')}}>Wyczyść wybór</button><details><summary>Dane szczegółowe</summary><pre>{JSON.stringify(current,null,2)}</pre></details>{:else}<Box size={28}/><h2>Wybierz część</h2><p>Kliknij pozycję na liście lub geometrię w podglądzie, aby zobaczyć nazwę, ruch i przyczynę ostrzeżenia.</p>{/if}</aside>
 {/if}</div>
 <div class="legend-panel"><span>Wspólna legenda statusów</span>{#each ['SAME','MOVED','CHANGED','ADDED','REMOVED','UNCERTAIN'] as status}<span><i style={`background:${color(status)}`}></i>{statuses[status]}</span>{/each}</div> <details class="panel alignment-panel"><summary>Położenie całego złożenia i ruch części</summary>{#if alignment.translation_B_to_A_mm}<div class="alignment-values"><strong>Wyrównanie B → A</strong>{#each ['X','Y','Z'] as axis,i}<span>{axis}: {number(alignment.translation_B_to_A_mm[i])}</span>{/each}<span>{alignment.applied?'Zastosowano':'Nie zastosowano'}</span></div>{:else}<p>Nie zastosowano wyrównania całego złożenia.</p>{/if}<p>Wektory części opisują ruch A → B{alignment.applied?' po wyrównaniu złożeń':' w położeniu użytym do analizy'}. W podglądzie HTML możesz przełączyć położenie B oraz porównać A i B ze wspólną kamerą.</p></details>

{:else}<div class="empty"><Box size={44}/><h2>Wyniki pojawią się tutaj</h2><button onclick={onopen}>Otwórz folder wyników</button></div>{/if}
